// ---------------------------------------------------------------------------
// Normalisation primitives.
// Everything that turns messy scraped text into a comparable value lives here.
// Pure functions only - no I/O - so the same code runs in tests, in n8n Code
// nodes (inlined by n8n/build.mjs) and in scripts.
// ---------------------------------------------------------------------------

const US_STATES = {
  alabama: 'AL', alaska: 'AK', arizona: 'AZ', arkansas: 'AR', california: 'CA',
  colorado: 'CO', connecticut: 'CT', delaware: 'DE', 'district of columbia': 'DC',
  florida: 'FL', georgia: 'GA', hawaii: 'HI', idaho: 'ID', illinois: 'IL',
  indiana: 'IN', iowa: 'IA', kansas: 'KS', kentucky: 'KY', louisiana: 'LA',
  maine: 'ME', maryland: 'MD', massachusetts: 'MA', michigan: 'MI', minnesota: 'MN',
  mississippi: 'MS', missouri: 'MO', montana: 'MT', nebraska: 'NE', nevada: 'NV',
  'new hampshire': 'NH', 'new jersey': 'NJ', 'new mexico': 'NM', 'new york': 'NY',
  'north carolina': 'NC', 'north dakota': 'ND', ohio: 'OH', oklahoma: 'OK',
  oregon: 'OR', pennsylvania: 'PA', 'rhode island': 'RI', 'south carolina': 'SC',
  'south dakota': 'SD', tennessee: 'TN', texas: 'TX', utah: 'UT', vermont: 'VT',
  virginia: 'VA', washington: 'WA', 'west virginia': 'WV', wisconsin: 'WI',
  wyoming: 'WY'
};

const STATE_CODES = new Set(Object.values(US_STATES));

// Legal-entity and decorative suffixes that must not make two rows look different.
const NAME_NOISE = [
  'llc', 'l l c', 'inc', 'inc.', 'incorporated', 'corp', 'corporation', 'co',
  'company', 'ltd', 'limited', 'plc', 'pllc', 'pc', 'pa', 'dds', 'md', 'dmd',
  'the', 'official', 'shop', 'store', 'usa', 'us'
];

function stripDiacritics(value) {
  return String(value ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function collapseWhitespace(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

/** Display-safe business name: trimmed, de-emojied, single-spaced. */
function cleanBusinessName(value) {
  if (!value) return null;
  const cleaned = collapseWhitespace(
    stripDiacritics(value)
      .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, ' ')
      .replace(/[|•·–—]+/g, ' ')
  );
  return cleaned || null;
}

/**
 * Comparison key for a business name. Lowercase, no punctuation, no legal
 * suffixes, no filler words. "Glow Med Spa, LLC" and "glow medspa" collapse to
 * the same key, which is what the dedupe layer matches on.
 */
function normalizeBusinessName(value) {
  const base = cleanBusinessName(value);
  if (!base) return null;
  const tokens = base
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .filter((t) => !NAME_NOISE.includes(t));
  // "med spa" -> "medspa", "hair salon" -> "hairsalon" is too aggressive; only
  // collapse the two-token forms that are genuinely written both ways.
  const joined = tokens.join(' ')
    .replace(/\bmed spa\b/g, 'medspa')
    .replace(/\bday spa\b/g, 'dayspa')
    .replace(/\be commerce\b/g, 'ecommerce');
  return joined || null;
}

/** Instagram handle without @, url wrapper, query string or trailing slash. */
function normalizeHandle(value) {
  if (!value) return null;
  let handle = String(value).trim();
  const urlMatch = handle.match(/instagram\.com\/([^/?#]+)/i);
  if (urlMatch) handle = urlMatch[1];
  handle = handle.replace(/^@+/, '').replace(/\/+$/, '').split('?')[0].trim().toLowerCase();
  if (!handle) return null;
  // Instagram handles: letters, numbers, periods, underscores, max 30 chars.
  if (!/^[a-z0-9._]{1,30}$/.test(handle)) return null;
  const reserved = new Set(['p', 'reel', 'reels', 'explore', 'stories', 'accounts', 'direct', 'tv']);
  if (reserved.has(handle)) return null;
  return handle;
}

function instagramUrl(handle) {
  const h = normalizeHandle(handle);
  return h ? `https://www.instagram.com/${h}/` : null;
}

/** Absolute, lowercase-host URL with tracking parameters removed. */
function normalizeUrl(value) {
  if (!value) return null;
  let raw = String(value).trim();
  if (!raw || raw === '-' || raw.toLowerCase() === 'n/a') return null;
  if (!/^https?:\/\//i.test(raw)) raw = `https://${raw}`;
  let url;
  try {
    url = new URL(raw);
  } catch {
    return null;
  }
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(url.hostname)) return null;
  for (const key of [...url.searchParams.keys()]) {
    if (/^(utm_|fbclid|gclid|mc_|ref|source)/i.test(key)) url.searchParams.delete(key);
  }
  url.hostname = url.hostname.toLowerCase();
  url.hash = '';
  const path = url.pathname.replace(/\/+$/, '');
  return `${url.protocol}//${url.hostname}${path}${url.search}`;
}

// Link-in-bio aggregators are not a website - they must never become a dedupe key.
const AGGREGATOR_DOMAINS = new Set([
  'linktr.ee', 'link.tree', 'beacons.ai', 'bio.link', 'linkin.bio', 'msha.ke',
  'taplink.cc', 'lnk.bio', 'solo.to', 'campsite.bio', 'linkpop.com', 'many.link',
  'instagram.com', 'facebook.com', 'm.facebook.com', 'business.facebook.com',
  'tiktok.com', 'youtube.com', 'twitter.com', 'x.com', 'wa.me', 'api.whatsapp.com',
  'g.page', 'goo.gl', 'maps.google.com', 'yelp.com', 'booksy.com', 'vagaro.com',
  'square.site', 'squareup.com', 'calendly.com', 'sites.google.com'
]);

function isAggregatorDomain(domain) {
  if (!domain) return false;
  const d = String(domain).toLowerCase().replace(/^www\./, '');
  return AGGREGATOR_DOMAINS.has(d);
}

/** Registrable-ish domain: host without www, aggregators rejected. */
function normalizeDomain(value) {
  const url = normalizeUrl(value);
  if (!url) return null;
  let host;
  try {
    host = new URL(url).hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return null;
  }
  if (isAggregatorDomain(host)) return null;
  return host;
}

/** US phone to E.164. Anything that is not a plausible US number returns null. */
function normalizePhone(value, defaultCountry = '1') {
  if (!value) return null;
  const raw = String(value);
  if (/ext|x\d{3,}/i.test(raw) === false && raw.trim().startsWith('+')) {
    const intl = raw.replace(/[^\d+]/g, '');
    if (/^\+\d{8,15}$/.test(intl)) return intl;
  }
  const digits = raw.replace(/\D/g, '');
  if (!digits) return null;
  let national = digits;
  if (national.length === 11 && national.startsWith('1')) national = national.slice(1);
  if (national.length !== 10) return null;
  if (/^[01]/.test(national)) return null;              // invalid NANP area code
  if (/^(\d)\1{9}$/.test(national)) return null;        // 5555555555 style junk
  return `+${defaultCountry}${national}`;
}

function normalizeEmail(value) {
  if (!value) return null;
  const email = String(value).trim().toLowerCase().replace(/^mailto:/, '');
  if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/.test(email)) return null;
  const local = email.split('@')[0];
  if (/^(noreply|no-reply|donotreply|postmaster|abuse|privacy)$/.test(local)) return null;
  return email;
}

/** Accepts "California", "california", "CA", "Calif." -> "CA". */
function normalizeState(value) {
  if (!value) return null;
  const raw = String(value).trim();
  const upper = raw.toUpperCase();
  if (STATE_CODES.has(upper)) return upper;
  const key = stripDiacritics(raw).toLowerCase().replace(/[^a-z\s]/g, '').trim();
  if (US_STATES[key]) return US_STATES[key];
  const prefix = Object.keys(US_STATES).find((name) => name.startsWith(key) && key.length >= 4);
  return prefix ? US_STATES[prefix] : null;
}

function normalizeCity(value) {
  if (!value) return null;
  const city = collapseWhitespace(stripDiacritics(value).replace(/[^\p{L}\s.'-]/gu, ' '));
  if (!city || city.length < 2) return null;
  return city
    .toLowerCase()
    .split(' ')
    .map((w) => (w.length > 2 || /^(st|ft)$/.test(w) ? w[0].toUpperCase() + w.slice(1) : w))
    .join(' ');
}

function slug(value) {
  return stripDiacritics(String(value ?? ''))
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '')
    .slice(0, 40);
}

/** "12.3k" / "1,234" / "2.1M" -> integer. */
function parseCount(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? Math.round(value) : null;
  const raw = String(value).trim().toLowerCase().replace(/,/g, '').replace(/\s/g, '');
  const match = raw.match(/^([\d.]+)([km])?$/);
  if (!match) return null;
  const n = Number.parseFloat(match[1]);
  if (!Number.isFinite(n)) return null;
  const mult = match[2] === 'k' ? 1e3 : match[2] === 'm' ? 1e6 : 1;
  return Math.round(n * mult);
}

function toIsoDate(value) {
  if (!value) return null;
  const d = value instanceof Date ? value : new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function daysSince(value, now = new Date()) {
  const iso = toIsoDate(value);
  if (!iso) return null;
  return Math.floor((now.getTime() - new Date(iso).getTime()) / 86400000);
}

/**
 * Normalise a raw discovery row into the canonical lead shape every downstream
 * step expects. Unknown provider fields are kept under `raw`.
 */
function normalizeRawLead(raw = {}) {
  const pick = (...keys) => {
    for (const k of keys) {
      const v = k.split('.').reduce((o, part) => (o == null ? o : o[part]), raw);
      if (v !== undefined && v !== null && v !== '') return v;
    }
    return null;
  };

  const name = cleanBusinessName(pick('business_name', 'name', 'title', 'fullName', 'ownerFullName'));
  const handle = normalizeHandle(pick('instagram_handle', 'username', 'instagram', 'instagramUrl', 'instagram_url'));
  const website = normalizeUrl(pick('website', 'url', 'externalUrl', 'external_url', 'site'));
  const domain = normalizeDomain(website);
  const state = normalizeState(pick('state', 'region', 'administrativeArea', 'address.state'));
  const city = normalizeCity(pick('city', 'locality', 'address.city'));
  const products = toProductList(pick('products_services', 'products', 'services', 'menu', 'categories'));

  return {
    business_name: name,
    name_normalized: normalizeBusinessName(name),
    instagram_handle: handle,
    instagram_url: instagramUrl(handle) ?? normalizeUrl(pick('instagram_url', 'instagramUrl')),
    website,
    website_domain: domain,
    email: normalizeEmail(pick('email', 'emails.0', 'contact_email')),
    phone: pick('phone', 'phoneNumber', 'phone_number', 'telephone'),
    phone_e164: normalizePhone(pick('phone', 'phoneNumber', 'phone_number', 'telephone')),
    country: pick('country', 'countryCode') ?? 'US',
    state,
    city,
    postal_code: pick('postal_code', 'postalCode', 'zip'),
    address: pick('address', 'formattedAddress', 'street'),
    latitude: numberOrNull(pick('latitude', 'location.lat', 'lat')),
    longitude: numberOrNull(pick('longitude', 'location.lng', 'lng')),
    category: pick('category', 'categoryName', 'businessCategoryName', 'business_category'),
    bio: pick('bio', 'biography', 'description'),
    website_description: pick('website_description', 'meta_description'),
    products_services: products,
    products_count: products.length || parseCount(pick('products_count', 'productsCount')),
    ig_followers: parseCount(pick('ig_followers', 'followersCount', 'followers', 'follower_count')),
    ig_following: parseCount(pick('ig_following', 'followsCount', 'following')),
    ig_posts: parseCount(pick('ig_posts', 'postsCount', 'posts', 'media_count')),
    ig_is_business: boolOrNull(pick('ig_is_business', 'isBusinessAccount', 'is_business_account')),
    ig_is_private: boolOrNull(pick('ig_is_private', 'private', 'is_private')),
    ig_is_verified: boolOrNull(pick('ig_is_verified', 'verified', 'is_verified')),
    ig_last_post_at: toIsoDate(pick('ig_last_post_at', 'latestPostDate', 'last_post_at')),
    ig_external_url: normalizeUrl(pick('externalUrl', 'external_url', 'bio_link')),
    place_id: pick('place_id', 'placeId', 'fid'),
    source: pick('source', '_source') ?? 'unknown',
    source_search_term: pick('search_term', 'searchString', 'query'),
    raw
  };
}

function numberOrNull(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function boolOrNull(v) {
  if (v === true || v === false) return v;
  if (v === 'true') return true;
  if (v === 'false') return false;
  return null;
}

/** Products/services arrive as arrays, comma strings or objects. */
function toProductList(value) {
  if (!value) return [];
  let items = [];
  if (Array.isArray(value)) items = value;
  else if (typeof value === 'string') items = value.split(/[,;|\n]/);
  else if (typeof value === 'object') items = Object.values(value);
  const seen = new Set();
  const out = [];
  for (const item of items) {
    const label = collapseWhitespace(
      typeof item === 'string' ? item : (item?.name ?? item?.title ?? item?.label ?? '')
    );
    if (!label || label.length < 2 || label.length > 120) continue;
    const key = label.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(label);
  }
  return out;
}

// ---- lib/v1/schema.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// The V1 internal schema. Every input file, whatever its columns, is mapped
// onto this shape, and the original values are preserved alongside it so any
// lead can be traced back to the exact spreadsheet row it came from.
// ---------------------------------------------------------------------------

const LEAD_FIELDS = [
  'company_name', 'website', 'domain', 'industry', 'category',
  'country', 'state', 'city', 'address', 'postal_code',
  'employees', 'revenue',
  'contact_name', 'first_name', 'last_name', 'job_title', 'email', 'phone',
  'linkedin', 'company_linkedin', 'facebook', 'twitter', 'instagram',
  'google_maps_url', 'rating', 'review_count',
  'company_description', 'technologies',
  'source', 'source_file', 'original_row'
];

/** The record written to the output sheet, in column order. */
const OUTPUT_FIELDS = [
  'lead_id',
  'company_name', 'website', 'industry', 'country', 'state', 'city', 'employees',
  'overall_score', 'customer_support_score', 'ai_voice_score', 'classification',
  'business_instagram', 'instagram_confidence',
  'owner_name', 'owner_instagram', 'owner_instagram_confidence',
  'niche_match', 'niche_match_reason', 'excluded', 'exclusion_reason',
  'recommended_offer', 'offer_reason',
  'personalized_instagram_dm',
  'opportunity_signals',
  'research_summary',
  'evidence_sources',
  'phone', 'email', 'rating', 'review_count',
  'score_reasons',
  'review_status',
  'source_file', 'original_row',
  'duplicate_of', 'related_locations',
  'pipeline_notes'
];

const REVIEW_STATUSES = ['PENDING', 'APPROVED', 'REJECTED', 'CONTACTED'];
const CLASSIFICATIONS = ['BEST', 'GOOD', 'REVIEW', 'BAD'];
const OFFERS = ['CUSTOMER_SUPPORT', 'AI_VOICE', 'BOTH', 'NONE'];
const CONFIDENCE = ['HIGH', 'MEDIUM', 'LOW', 'NOT_FOUND'];

/** Classification thresholds. Configurable in config/v1.json. */
const DEFAULT_BANDS = [
  { label: 'BEST', min: 80 },
  { label: 'GOOD', min: 65 },
  { label: 'REVIEW', min: 50 },
  { label: 'BAD', min: 0 }
];

function classify(score, bands = DEFAULT_BANDS) {
  for (const band of [...bands].sort((a, b) => b.min - a.min)) {
    if (score >= band.min) return band.label;
  }
  return 'BAD';
}

function emptyLead() {
  return Object.fromEntries(LEAD_FIELDS.map((f) => [f, null]));
}

// ---- lib/v1/map-columns.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Column detection and row mapping - the pure half of ingestion.
//
// Separate from ingest.js because this module has no filesystem imports, which
// is what lets n8n/build.mjs inline it into an n8n Code node. ingest.js adds
// the file reading on top for the CLI.
// ---------------------------------------------------------------------------


// Every alias is compared after lowercasing and collapsing punctuation, so
// "Business Name", "business_name" and "BUSINESS-NAME" all match.
const COLUMN_ALIASES = {
  company_name: ['company', 'business', 'business name', 'company name', 'name', 'organisation', 'organization', 'practice', 'practice name', 'account name', 'dba'],
  website: ['website', 'url', 'web', 'site', 'web address', 'homepage', 'website url', 'company website', 'domain', 'company domain'],
  industry: ['industry', 'sector', 'vertical', 'niche'],
  category: ['category', 'type', 'business type', 'primary category', 'categories'],
  keywords: ['keywords', 'tags', 'search keywords'],
  country: ['country', 'country code'],
  state: ['state', 'province', 'region', 'state province'],
  city: ['city', 'town', 'locality'],
  address: ['address', 'street', 'street address', 'full address', 'location', 'formatted address', 'company raw address', 'company street address'],
  postal_code: ['zip', 'zipcode', 'zip code', 'postal', 'postal code', 'postcode', 'company postal code'],
  employees: ['employees', 'employee count', 'employees count', 'headcount', 'company size', 'staff', 'num employees'],
  revenue: ['revenue', 'annual revenue', 'turnover', 'company annual revenue', 'company annual revenue clean'],
  founded_year: ['founded', 'founded year', 'company founded year', 'year founded'],
  contact_name: ['contact', 'contact name', 'full name', 'owner', 'owner name', 'decision maker'],
  first_name: ['first name', 'firstname', 'given name'],
  last_name: ['last name', 'lastname', 'surname', 'family name'],
  job_title: ['job title', 'position', 'role', 'designation', 'headline'],
  seniority: ['seniority', 'seniority level'],
  department: ['department', 'departments', 'function'],
  email: ['email', 'e mail', 'email address', 'contact email', 'work email', 'primary email'],
  phone: ['phone', 'phone number', 'telephone', 'tel', 'contact number', 'primary phone', 'company phone number', 'company phone'],
  linkedin: ['linkedin', 'linkedin url', 'linkedin profile', 'personal linkedin'],
  company_linkedin: ['company linkedin', 'linkedin company', 'company linkedin url'],
  facebook: ['facebook', 'facebook url', 'fb', 'company facebook'],
  twitter: ['twitter', 'twitter url', 'x', 'x url', 'company twitter'],
  instagram: ['instagram', 'instagram url', 'instagram handle', 'ig', 'ig handle', 'company instagram'],
  google_maps_url: ['google maps', 'google maps url', 'maps url', 'gmb url', 'google url'],
  rating: ['rating', 'stars', 'average rating', 'google rating'],
  review_count: ['review count', 'reviews', 'number of reviews', 'total reviews', 'review total'],
  company_description: ['description', 'about', 'company description', 'summary', 'bio', 'notes', 'snippet', 'company short description', 'company seo description'],
  technologies: ['technologies', 'tech', 'tech stack', 'technology', 'company technologies'],
  // The business's own location, which is not always where the contact sits.
  company_city: ['company city'],
  company_state: ['company state'],
  company_country: ['company country']
};

// Columns deliberately left unmapped. A person's mobile number and personal
// email address are not what a cold business approach should use, so they are
// not carried into the pipeline even when a file supplies them.
const DELIBERATELY_IGNORED = ['mobile number', 'personal email', 'person photo', 'person id', 'company id', 'company logo', 'company linkedin uid'];

const squash = (value) => String(value ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

/**
 * Map headers onto V1 fields. Several headers may feed one field, in the order
 * they appear - the first non-empty value wins at read time.
 */
function detectColumns(headers) {
  const mapping = {};
  const matched = new Set();

  // "Title" means the place name in a Google Maps export and the person's job
  // title in a CRM export. If the file names the company some other way, Title
  // is a job title - otherwise it is the company name.
  const hasCompanyColumn = headers.some((h) =>
    ['company', 'business', 'business name', 'company name', 'account name', 'organisation', 'organization'].includes(squash(h))
  );
  const titleField = hasCompanyColumn ? 'job_title' : 'company_name';

  const ignored = [];
  for (const header of headers) {
    const key = squash(header);
    if (!key) continue;
    if (DELIBERATELY_IGNORED.includes(key)) { ignored.push(header); continue; }
    if (key === 'title') {
      (mapping[titleField] ??= []).push(header);
      matched.add(header);
      continue;
    }
    for (const [field, aliases] of Object.entries(COLUMN_ALIASES)) {
      if (aliases.includes(key)) {
        (mapping[field] ??= []).push(header);
        matched.add(header);
        break;
      }
    }
  }
  const ignoredSet = new Set(ignored);
  return {
    mapping,
    ignored,
    unmapped: headers.filter((h) => h && !matched.has(h) && !ignoredSet.has(h))
  };
}

/** Map one raw row onto the V1 schema. */
function mapRow(row, mapping, { sourceFile, sourceLabel }) {
  const pick = (field) => {
    for (const header of mapping[field] ?? []) {
      const value = row[header];
      if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
    }
    return null;
  };

  const lead = emptyLead();
  const rawName = pick('company_name');
  lead.company_name = cleanBusinessName(rawName);
  lead.name_normalized = normalizeBusinessName(rawName);
  lead.website = normalizeUrl(pick('website'));
  lead.domain = normalizeDomain(lead.website);
  lead.industry = pick('industry');
  lead.category = pick('category');
  // The company's location wins over the contact's: a courier in Calgary with
  // an owner living in London, Ontario is a Calgary business.
  lead.country = pick('company_country') ?? pick('country') ?? 'US';
  const rawState = pick('company_state') ?? pick('state');
  lead.state = normalizeState(rawState) ?? rawState;
  lead.city = normalizeCity(pick('company_city') ?? pick('city'));
  lead.contact_city = normalizeCity(pick('city'));
  lead.address = pick('address');
  lead.postal_code = (pick('postal_code') ?? '').replace(/\.0$/, '') || null;
  lead.employees = parseCount(pick('employees'));
  lead.revenue = pick('revenue');
  lead.contact_name = pick('contact_name');
  lead.first_name = pick('first_name');
  lead.last_name = pick('last_name');
  lead.job_title = pick('job_title');
  lead.email = normalizeEmail(pick('email'));
  lead.phone = pick('phone');
  lead.phone_e164 = normalizePhone(pick('phone'));
  lead.linkedin = normalizeUrl(pick('linkedin'));
  lead.company_linkedin = normalizeUrl(pick('company_linkedin'));
  lead.facebook = normalizeUrl(pick('facebook'));
  lead.twitter = normalizeUrl(pick('twitter'));
  lead.instagram = normalizeHandle(pick('instagram'));
  lead.google_maps_url = normalizeUrl(pick('google_maps_url'));
  const ratingRaw = pick('rating');   // Number(null) is 0, so check for absence first
  lead.rating = ratingRaw !== null && Number.isFinite(Number(ratingRaw)) ? Number(ratingRaw) : null;
  lead.review_count = parseCount(pick('review_count'));
  lead.company_description = pick('company_description');
  lead.technologies = toProductList(pick('technologies'));
  lead.keywords = toProductList(pick('keywords'));
  lead.seniority = pick('seniority');
  lead.department = pick('department');
  lead.founded_year = pick('founded_year');

  lead.source = sourceLabel ?? 'attached_file';
  lead.source_file = sourceFile;
  lead.original_row = row.__row ?? null;
  // Nothing from the original row is discarded.
  lead.original_record = Object.fromEntries(
    Object.entries(row).filter(([k, v]) => k !== '__row' && v !== null && String(v).trim() !== '')
  );
  return lead;
