  const sameCity = (a.city ?? '').toLowerCase() === (b.city ?? '').toLowerCase() && Boolean(a.city);
  const sameState = (a.state ?? '').toUpperCase() === (b.state ?? '').toUpperCase() && Boolean(a.state);
